messages.body_plain:
I have my desired format for the UI, and in my survey I'm going to be asking roughly 100 questions. Since that's the case, a for loop would be a lot more efficient instead of recreating it over and over. The problem is that I have radio buttons, next and previous buttons, and a remote file output as a csv. Is it even possible to make this into a loop where the outputs are recognizable and belong to specific radio button selections? Here's what I have so far:

library(shiny)
library(shinydashboard)
library(rdrop2)
library(shinyjs)
library(shinyBS)
library(shinyWidgets)

fields <- c("radio1", "radio2", "radio3", "radio4", "radio5", "radio6"
             ")

ui <- dashboardPage(skin = "blue",

  dashboardHeader(titleWidth = "0%"

  ),
  dashboardSidebar(disable=TRUE,
    sidebarMenu(id = "tabs",
      menuItem("Dashboard", tabName = "dashboard", icon = icon("dashboard")
      ),
      menuItem("Question Type One", tabName = "known", icon = icon("shoe-prints"),
               menuSubItem("Question 1", tabName = "q_1", icon = icon("angle-double-right")),
               menuSubItem("Question 2", tabName = "q_2", icon = icon("angle-double-right")),

    )
  ),
  dashboardBody(
    tags$head(
    tags$style(
      HTML(".shiny-notification {
             position:fixed;
             top: calc(39%);
             left: calc(44.6%);
             }
             "
      )
    )
  ),

    DT::dataTableOutput("responses", width = 300), tags$hr(),

    tabItems(
      tabItem(tabName = "dashboard",
              h2("Placeholder for directions and any other general statements.",
                 br(),
                 br(),
                 actionButton("jump1", "Next", icon("long-arrow-alt-right"), class = "btn-primary", style="float:right;text-align:center")

              )
      ),

     tabItem(tabName = "q_1",
             fluidRow(box(height=0,width=2,solidHeader = TRUE),box(height=NULL, width=8,h3("-
                                                  "), align="center"), box(height=0,width=2,solidHeader = TRUE)),
             fluidRow(box(height=0,width=1,solidHeader = TRUE), box(height=NULL, width=2, radioButtons("radio1", label = strong("-"),
                                                                                   choices = list("-" = 5, "-" = 4, "-" = 3, "-" = 2, "-" = 1),
                                                                                   selected = character("0")),style="text-align:center"),
                      box(height=NULL, width=3, tags$img(src='trial.png', height=415, width=415, style="display: block; margin-left: auto; margin-right: auto;")),
                      box(height=NULL, width=3, tags$img(src='trial.png', height=415, width=415, style="display: block; margin-left: auto; margin-right: auto;")), box(height=NULL, width=2,
                                                                                            radioButtons("radio2", label = strong("-"),
                                                                                                         choices = list("-" = 5, "- " = 4, "-" = 3, "-" = 2, "-" = 1),
                                                                                                         selected = character(0)),style="text-align:center"), box(height=0, width=1,solidHeader = TRUE)),
             fluidRow(box(height=0, width=2,solidHeader = TRUE), box(height= NULL, width=8, h3("Please indicate the complexity of the Randomly Acquired Characteristics in comparison with one another."), align="center"), box(height=0, width=2,solidHeader = TRUE)),
             fluidRow(box(height=0, width=2,solidHeader = TRUE), box(height=NULL, width=8, radioButtons("radio3", label = NULL, choices = list("-" = 1, "-" = 2, "-" = 3, "-" = 4, "-" = 5),
                                                                                     selected = character(0), inline=TRUE), align="center"), box(height=0, width=2,solidHeader = TRUE)),
           fluidRow(
                         box(height=0,width=1,solidHeader = TRUE,div(style="width:100%;text-align:center;",bsButton("jump3", "Previous", icon("long-arrow-alt-left"), style = "primary"))),
                         box(height=0,width=10,solidHeader = TRUE),
                    box(height=0,width=1,solidHeader = TRUE,div(style="width:100%;text-align:center;",bsButton("jump2","Next", icon("long-arrow-alt-right"), style = "primary")))
                    ),
             br(),
             br(),
             progressBar(id = "pb1", value = 0),
             fluidRow(box(height=1, width=12)))

     )
    )
  )

server <- shinyServer(function(input, output, session) {
 #--------------------------------------------------------------------
   observeEvent({input$jump1}, ({

    widget2_right <- ({input$radio2
      input$radio1
      input$radio3})

    print(widget2_right)

    if(length(widget2_right) == 0) {
      updateButton(session, "jump2", disabled = TRUE)
    } else {
      updateButton(session, "jump2", disabled = FALSE)
    }

  }))
  observeEvent({input$radio3
    }, ({

    widget2_right <- ({input$radio1
      input$radio2
     })

    print(widget2_right)

    if(length(widget2_right) != 0) {
      updateButton(session, "jump2", disabled = FALSE)
    } else {
      updateButton(session, "jump2", disabled = TRUE)
    }
  }))

 #------------------------------------------------------------------
    observeEvent(input$jump2, {
    for (i in 1:100) {
      updateProgressBar(
        session = session,
        id = "pb1",
        value = 10, total = 100,
        title = paste("Process", trunc(i/10))
      )
      Sys.sleep(0.001)
    }
  })
  observeEvent(input$jump4, {
    for (i in 1:100) {
      updateProgressBar(
        session = session,
        id = "pb2",
        value = 20, total = 100,
        title = paste("Process", trunc(i/10))
      )
      Sys.sleep(0.001)
    }
  })
  observeEvent(input$jump6, {
    for (i in 1:100) {
      updateProgressBar(
        session = session,
        id = "pb3",
        value = 30, total = 100,
        title = paste("Process", trunc(i/10))
      )
      Sys.sleep(0.001)
    }
  })
  observeEvent(input$jump8, {
    for (i in 1:100) {
      updateProgressBar(
        session = session,
        id = "pb4",
        value = 40, total = 100,
        title = paste("Process", trunc(i/10))
      )
      Sys.sleep(0.001)
    }
  })
  observeEvent(input$jump10, {
    for (i in 1:100) {
      updateProgressBar(
        session = session,
        id = "pb5",
        value = 50, total = 100,
        title = paste("Process", trunc(i/10))
      )
      Sys.sleep(0.001)
    }
  })

  observeEvent(input$submit, {
    showNotification("Thank you for your response. You may now close out of this browser.", duration = 50, closeButton = NULL, type= c("error"))
  })

  observeEvent(input$jump1, {
    newtab <- switch(input$tabs, "q_1")
    updateTabItems(session, "tabs", newtab)
  })

  observeEvent(input$jump2, {
    newtab <- switch(input$tabs, "q_2")
    updateTabItems(session, "tabs", newtab)
  })

  observeEvent(input$jump3, {
    newtab <- switch(input$tabs, "dashboard")
    updateTabItems(session, "tabs", newtab)
  })

  observeEvent(input$jump4, {
    newtab <- switch(input$tabs, "q_3")
    updateTabItems(session, "tabs", newtab)
  })

  observeEvent(input$jump5, {
    newtab <- switch(input$tabs, "q_1")
    updateTabItems(session, "tabs", newtab)
  })

  formData <- reactive({

    data <- sapply(fields, function(x) input[[x]])

    data

  })

  observeEvent(input$submit, {

    saveData(formData())

  })

  output$responses <- DT::renderDataTable({

    input$submit

    loadData()

  })

  saveData <- function(data) {

    data <- as.data.frame(t(data))

    if (exists("responses")) {

      responses <<- rbind(responses, data)

    } else {

      responses <<- data

    }

  }

  loadData <- function() {

    if (exists("responses")) {

      responses

    }

  }

  outputDir <- "responses"

  saveData <- function(data) {

    data <- t(data)

    fileName <- sprintf("%s_%s.csv", as.integer(Sys.time()), digest::digest(data))

    filePath <- file.path(tempdir(), fileName)

    write.csv(data, filePath, row.names = FALSE, quote = TRUE)

    drop_upload(filePath, path = outputDir)

  }

}

)

shinyApp(ui, server)

Thank you in advanced for any help.
